                row:{ add:[{ id:'id=32', tag:'x', sub:'c=200  ·  implicit X  (클러스터 먼저)' }] },
                idx:{ span:{ del:['conv'], add:[{ id:'s200', from:100, to:200, kind:'next', lb:'S  next-key  (중복 검사)', row:0 }] } },
                tl:{ add:[{ id:'t · AUTO_INC', tag:'hold', sub:'경합 없어도 잡는다' }] },
