  num:'14', tab:'Implicit Locks', title:'Implicit Locks: An INSERT Leaves No Lock Struct',
  sub:'INSERT 한 레코드는 DB_TRX_ID 로 잠긴다 — 다른 trx 가 락을 물을 때 비로소 explicit X,REC_NOT_GAP 이 된다',
