    fact:['trx = trx_rw_is_active(trx_id, true);',
          'if (!trx_state_eq(trx, TRX_STATE_COMMITTED_IN_MEMORY) &&',
          ['storage/innobase/trx/trx0trx.cc','lock_trx_release_locks(trx);']],
